-- ---------------------------------------------------------------------------
-- Phase 6 — FAQ content (PROJECT_PLAN.md)
--
-- Replaces the Alam FAQs and FAQ categories with the /ci3/ FAQ page, and sets
-- the FAQ page (Web Pages 6) hero, sections and meta. The hidden "Home Page"
-- category (cat_id 1) is kept, without questions.
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;

DELETE FROM `faqs`;
DELETE FROM `faqs_categories` WHERE `cat_id` > 1;


UPDATE `pages` SET
    `banner_title` = 'Good to know',
    `banner_heading` = 'Questions we''re asked a lot',
    `banner_text` = 'Booking, nails and finding the salon. If yours isn''t here, give us a call — we''d rather answer properly than guess.',
    `banner_background` = '',
    `meta_description` = 'Common questions about booking, manicures, gel nails and visiting Blossom Ewa Mazur in Gorlice.'
WHERE `page_id` = 6;

DELETE FROM `web_page_sections` WHERE `page_id` = 6 AND `section_key` NOT IN ('sidebar', 'questions', 'links', 'cta');

